type AdminAuction struct {
	BidCount   int        `json:"bidCount"`
	CategoryId CategoryId `json:"categoryId"`
	Code       string     `json:"code"`

	// CurrentPriceIdr Best bid per unit so far (lowest for reverse, highest for forward); absent for sealed. Current ask for Dutch.
	CurrentPriceIdr *int      `json:"currentPriceIdr,omitempty"`
	EndsAt          time.Time `json:"endsAt"`
	Findings        []Finding `json:"findings"`
	Id              string    `json:"id"`
	Lot             struct {
		Item     string   `json:"item"`
		Quantity Quantity `json:"quantity"`
		Spec     string   `json:"spec"`
	} `json:"lot"`
	MarketId        string    `json:"marketId"`
	MarketName      string    `json:"marketName"`
	OpeningPriceIdr int       `json:"openingPriceIdr"`
	Participants    int       `json:"participants"`
	StartsAt        time.Time `json:"startsAt"`

	// Status Auction lifecycle status.
	Status     AuctionStatus `json:"status"`
	Title      string        `json:"title"`
	Type       AuctionType   `json:"type"`
	Visibility BidVisibility `json:"visibility"`
}

